import{_ as o,o as t,c,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.6.9 — Approval Sequence (Creator -&gt; Manager -&gt; Client)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.md","filePath":"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.md"}'),n={name:"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.md"};function a(i,e,r,h,s,l){return t(),c("div",null,[...e[0]||(e[0]=[d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a> · <a href="./../../../../ba/13-task-status-and-approval-governance.html">BA Governance →</a></p><h1 id="fr-3-6-9-—-approval-sequence-creator-gt-manager-gt-client" tabindex="-1">FR 3.6.9 — Approval Sequence (Creator -&gt; Manager -&gt; Client) <a class="header-anchor" href="#fr-3-6-9-—-approval-sequence-creator-gt-manager-gt-client" aria-label="Permalink to &quot;FR 3.6.9 — Approval Sequence (Creator -&amp;gt; Manager -&amp;gt; Client)&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Thuộc tính</th><th style="text-align:left;">Giá trị</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Use Case</strong></td><td style="text-align:left;"><code>3.6.9</code> / <code>UC-061</code></td></tr><tr><td style="text-align:left;"><strong>Miền chức năng</strong></td><td style="text-align:left;"><code>3.6 Content &amp; Workflow</code></td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code> <em>(chặn <code>Guest</code> <code>401</code>; <code>Admin</code> vận hành <code>3.10.4</code> độc lập)</em></td></tr><tr><td style="text-align:left;"><strong>Vai trò tham gia trên Task</strong></td><td style="text-align:left;"><code>Coordinator</code> (<code>task.assigneeId</code>), <code>Task Supervisor</code> (<code>task.supervisorId</code>), <code>Section Owner</code> (<code>subtask.assigneeId</code>), <code>Subtask Supervisor</code> (<code>subtask.supervisorOverrideId</code>)</td></tr><tr><td style="text-align:left;"><strong>Phạm vi loại công việc</strong></td><td style="text-align:left;">Đầy đủ <strong>8 <code>TaskType</code></strong>: <code>POST</code>, <code>SHORT_VIDEO</code>, <code>SURVEY</code>, <code>EVENT_PLAN</code>, <code>PRESS_RECOMMENDATION</code>, <code>KOL_BOOKING</code>, <code>WORKSHOP</code>, <code>EMAIL_NEWSLETTER</code></td></tr><tr><td style="text-align:left;"><strong>Quy tắc nghiệp vụ liên quan</strong></td><td style="text-align:left;"><code>BR-33</code>, <code>BR-34</code>, <code>BR-34a</code> <em>(Anti-Self-Supervision)</em>, <code>BR-35</code>, <code>BR-42</code>, <code>BR-54</code></td></tr><tr><td style="text-align:left;"><strong>Phiên bản đặc tả</strong></td><td style="text-align:left;"><strong>v4.0 — Hợp nhất Phân quyền Đa Vai trò, Tự động Chốt Trạng thái &amp; Chống Nhảy cóc (27/11/2026)</strong></td></tr></tbody></table><hr><h2 id="_1-objective-muc-tieu-nghiep-vu" tabindex="-1">1. Objective (Mục tiêu Nghiệp vụ) <a class="header-anchor" href="#_1-objective-muc-tieu-nghiep-vu" aria-label="Permalink to &quot;1. Objective (Mục tiêu Nghiệp vụ)&quot;">​</a></h2><p>Đảm bảo mọi công việc sản xuất nội dung trên cả <strong>8 loại <code>TaskType</code></strong> đều đi qua luồng kiểm duyệt phân cấp chặt chẽ, minh bạch theo đúng vai trò trong Workspace (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>) và vai trò gắn trực tiếp trên từng Công việc / Công việc con (<code>Người thực hiện</code>, <code>Người giám sát</code>), đồng thời:</p><ol><li><strong>Tự động chuyển trạng thái Task cha (<code>IN_PROGRESS → IN_REVIEW → FINISHED</code>)</strong> ngay khi các phần nội dung (<code>TaskSection</code>) hoàn tất phê duyệt tương ứng, loại bỏ tình trạng duyệt xong 100% nhưng trạng thái bên ngoài vẫn kẹt ở <code>Đang làm</code>.</li><li><strong>Đóng kín mọi lỗ hổng nhảy cóc trạng thái</strong> qua API đổi status thô, kéo-thả Kanban, Thanh thao tác hàng loạt hoặc nút <code>Self-Approve</code> sai chế độ.</li><li><strong>Đồng bộ quyền đầy đủ cho <code>Owner</code> và <code>Người giám sát</code> (<code>supervisorId</code>)</strong>, ngăn chặn tuyệt đối việc <code>Creator</code> tự làm Người giám sát để bỏ qua bước duyệt nội bộ.</li></ol><hr><h2 id="_2-user-stories-theo-vai-tro-chuan" tabindex="-1">2. User Stories theo Vai trò Chuẩn <a class="header-anchor" href="#_2-user-stories-theo-vai-tro-chuan" aria-label="Permalink to &quot;2. User Stories theo Vai trò Chuẩn&quot;">​</a></h2><ul><li><strong>Là một <code>Creator</code> (Chủ phần <code>Section Owner</code> hoặc Điều phối viên <code>Coordinator</code>)</strong>: Tôi muốn biên soạn, lưu nháp (tự động kích hoạt Task từ <code>TODO</code> sang <code>IN_PROGRESS</code> nếu đủ điều kiện) và nộp duyệt từng phần việc được giao mà không thể vô tình hay cố ý tự chuyển Task cha sang <code>FINISHED</code> khi chưa được cấp trên nghiệm thu.</li><li><strong>Là một <code>Task Supervisor</code> (<code>task.supervisorId</code>) hoặc <code>Subtask Supervisor</code> (<code>subtask.supervisorOverrideId</code>)</strong>: Tôi muốn có quyền kiểm duyệt nội bộ (<code>Approve</code> / <code>Return</code> kèm lý do) đối với các phần nội dung và công việc mình được phân công giám sát (miễn tôi không phải là người trực tiếp làm phần đó).</li><li><strong>Là một <code>Manager</code> hoặc <code>Owner</code> của Workspace <code>AGENCY</code></strong>: Tôi muốn có toàn quyền điều hành, chọn nền tảng xuất bản (<code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code>), phân công công việc con, phê duyệt / trả lại / mở lại (<code>Reopen</code>) bất kỳ phần nội dung nào (kể cả mở lại gấp trước giờ xuất bản), và theo dõi toàn bộ <strong>8 loại <code>TaskType</code></strong> tập trung tại trang <code>/workspaces/:id/task-approvals</code>.</li><li><strong>Là một <code>Client</code> trong Workspace <code>AGENCY</code></strong>: Tôi muốn chỉ nhìn thấy các phần sản phẩm đầu ra (<code>OUTPUT</code>) đã qua kiểm duyệt nội bộ của Agency (ẩn hoàn toàn các phần nội bộ <code>INTERNAL</code> và lịch sử nháp), và ngay khi tôi bấm <code>Duyệt</code> phần đầu ra cuối cùng thì công việc tự động chốt sang <code>Hoàn thành</code> (<code>FINISHED</code>).</li><li><strong>Là Chủ không gian chế độ <code>PERSONAL</code> (<code>Owner</code> / <code>Manager</code>)</strong>: Tôi muốn sử dụng nút <strong><code>Hoàn tất &amp; Tự duyệt</code> (<code>Self-Approve</code> 1 chạm)</strong> để chốt nhanh công việc cá nhân sang <code>FINISHED</code> mà không ảnh hưởng tới quy trình kiểm soát nhiều người của chế độ <code>AGENCY</code>.</li></ul><hr><h2 id="_3-acceptance-criteria-tieu-chi-nghiem-thu-chi-tiet" tabindex="-1">3. Acceptance Criteria (Tiêu chí Nghiệm thu Chi tiết) <a class="header-anchor" href="#_3-acceptance-criteria-tieu-chi-nghiem-thu-chi-tiet" aria-label="Permalink to &quot;3. Acceptance Criteria (Tiêu chí Nghiệm thu Chi tiết)&quot;">​</a></h2><h3 id="_3-1-phan-quyen-đa-vai-tro-owner-manager-creator-client-×-supervisor-assignee" tabindex="-1">3.1. Phân quyền Đa Vai trò (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code> × <code>Supervisor</code>, <code>Assignee</code>) <a class="header-anchor" href="#_3-1-phan-quyen-đa-vai-tro-owner-manager-creator-client-×-supervisor-assignee" aria-label="Permalink to &quot;3.1. Phân quyền Đa Vai trò (`Owner`, `Manager`, `Creator`, `Client` × `Supervisor`, `Assignee`)&quot;">​</a></h3><ul><li><strong>AC-01 — Đồng quyền điều hành của <code>Owner</code> với <code>Manager</code>:</strong> Trong mọi Workspace thuộc <code>Agency</code> của mình, <code>Owner</code> có đầy đủ quyền hạn như <code>Manager</code> trên toàn bộ vòng đời công việc: giao việc (<code>assign</code>), chọn và thay đổi nền tảng đích (<code>targetPlatforms</code>), thêm/sửa/sắp xếp công việc con (<code>Subtasks</code> cho cả task Chiến dịch và task Độc lập), bấm bắt đầu (<code>start</code>), sửa/nộp/khôi phục phần nội dung (<code>Section</code>), duyệt nội bộ (<code>APPROVE</code>), trả lại (<code>RETURN</code>), mở lại (<code>REOPEN</code>), và duyệt/từ chối Task cha ở bước <code>MANAGER</code>.</li><li><strong>AC-02 — Kế thừa Người giám sát (<code>Supervisor Inheritance</code>):</strong> Quy tắc xác định người giám sát hiệu lực của một công việc con / phần nội dung là: <code>subtask.supervisorOverrideId ?? task.supervisorId ?? defaultManager(workspaceId)</code>. Một thành viên là <code>Creator</code> được chỉ định làm <code>task.supervisorId</code> hoặc <code>subtask.supervisorOverrideId</code> (và không đồng thời là chủ sở hữu phần đó hay <code>Coordinator</code> tự duyệt bài mình) có quyền <code>APPROVE</code> / <code>RETURN</code> cấp nội bộ đối với phần/task đó.</li><li><strong>AC-03 — Duyệt hỗ trợ của <code>Owner</code> &amp; <code>Manager</code>:</strong> Kể cả khi Task đã gán <code>task.supervisorId</code> cụ thể, mọi <code>Owner</code> và <code>Manager</code> đang hoạt động trong Workspace (khác <code>Creator</code> nộp bài) đều có quyền thực hiện duyệt nội bộ hoặc trả lại để không gây tắc nghẽn dây chuyền khi Người giám sát vắng mặt.</li><li><strong>AC-04 — Chống tự giám sát (<code>BR-34a — Anti-Self-Supervision</code>):</strong><ul><li>Nếu người thực hiện (<code>task.assigneeId</code> hoặc <code>subtask.assigneeId</code>) có vai trò <code>Creator</code>, hệ thống <strong>cấm tuyệt đối</strong> gán người giám sát trùng với người thực hiện đó (<code>supervisorId != assigneeId</code>).</li><li>Khi <code>Creator</code> tạo mới công việc (<code>POST /tasks</code> hoặc <code>POST /tasks/standalone</code>) mà để trống <code>supervisorId</code> (hoặc gửi ID của chính mình), hệ thống bắt buộc gán <code>task.supervisorId = defaultManager</code> của Workspace.</li><li>Quy tắc bỏ qua bước duyệt nội bộ (<code>skipsAgencyReview</code>) <strong>chỉ</strong> kích hoạt khi người thực hiện chính (<code>task.assigneeId</code>) mang vai trò <code>Owner</code> hoặc <code>Manager</code> và tự giám sát chính mình (hoặc trong chế độ <code>PERSONAL</code>).</li></ul></li><li><strong>AC-05 — Cô lập <code>Creator</code> không tham gia Task:</strong> Một <code>Creator</code> trong Workspace nhưng không phải <code>task.assigneeId</code>, <code>task.supervisorId</code>, <code>subtask.assigneeId</code> hay <code>subtask.supervisorOverrideId</code> của Task thì: <ul><li>Không nhìn thấy các phần <code>INTERNAL</code> và không sửa được bất kỳ phần nào.</li><li>Không được sửa danh sách đối tác (<code>PATCH /tasks/{taskId}/partners</code> → <code>403 FORBIDDEN</code>).</li><li>Không được bấm xuất bản bài đăng của Task đó (<code>POST /posts/{postId}/publish</code> → <code>403 FORBIDDEN</code>).</li></ul></li><li><strong>AC-06 — Cô lập tầm nhìn và quyền của <code>Client</code>:</strong><ul><li><code>Client</code> chỉ nhìn thấy các <code>TaskSection</code> có <code>visibility = OUTPUT</code> đã đạt <code>INTERNAL_APPROVED</code> hoặc <code>CLIENT_APPROVED</code>; toàn bộ phần <code>INTERNAL</code> (<code>POST.BRIEF</code>, <code>VIDEO.SHOOT</code>, <code>KOL.DEAL</code>, <code>EVENT.LOGISTICS</code>, <code>EVENT.RUNSHEET</code>, <code>PRESS.MEDIA_LIST</code>, <code>PRESS.CONTACT_LOG</code>, <code>WORKSHOP.LOGISTICS</code>) và lịch sử phiên bản (<code>TaskSectionVersion</code>) bị lọc bỏ hoàn toàn từ Backend.</li><li>Một <code>Client</code> đang hoạt động bất kỳ trong Workspace được quyền quyết định (<code>CLIENT_APPROVE</code> / <code>CLIENT_RETURN</code>) khi <code>task.requiresClientApproval = true</code>.</li></ul></li></ul><h3 id="_3-2-go-ket-khoi-đong-tu-đong-chot-trang-thai-auto-settlement-chong-nhay-coc" tabindex="-1">3.2. Gỡ kẹt Khởi động, Tự động Chốt Trạng thái (<code>Auto-Settlement</code>) &amp; Chống Nhảy Cóc <a class="header-anchor" href="#_3-2-go-ket-khoi-đong-tu-đong-chot-trang-thai-auto-settlement-chong-nhay-coc" aria-label="Permalink to &quot;3.2. Gỡ kẹt Khởi động, Tự động Chốt Trạng thái (`Auto-Settlement`) &amp; Chống Nhảy Cóc&quot;">​</a></h3><ul><li><strong>AC-07 — Tự mở phiên làm việc cho Chủ phần (<code>Auto-Start on Subtask Edit</code>):</strong> Khi Task cha đang ở trạng thái <code>TODO</code> (đã có đủ mô tả Brief, hạn chót hợp lệ và Chiến dịch cho phép bắt đầu), nếu <code>Coordinator</code> hoặc bất kỳ <code>Section Owner</code> (<code>subtask.assigneeId</code>) hợp lệ nào lưu bản nháp phần nội dung (<code>PATCH /sections/{key}</code> hoặc <code>POST /tasks/{id}/post</code>), hệ thống tự động chuyển Task cha sang <code>IN_PROGRESS</code> (ghi nhận <code>firstStartedAt</code>, <code>firstStartedBy</code>), xóa bỏ sự bất nhất giữa phần <code>Brief</code> và phần <code>Caption</code>/<code>Media</code>.</li><li><strong>AC-08 — Tự động chốt Task cha khi làm theo từng phần (<code>Section → Subtask → Task Auto-Settlement</code>):</strong> Với mọi Task có <code>Subtask</code> gắn vai trò (<code>roleTask = true</code> trên cả 8 loại <code>TaskType</code>): <ol><li>Mỗi lần một phần được <code>APPROVE</code> (cấp nội bộ hoặc cấp <code>Client</code>), hệ thống đồng bộ trạng thái <code>Subtask</code> vai trò (<code>syncRoleSubtasks</code>) và kiểm tra toàn cục các phần của Task:</li><li>Các phần không có <code>Subtask</code> sở hữu riêng (<code>unowned sections</code>) được coi là sẵn sàng đóng nội bộ khi thỏa điều kiện nội dung tối thiểu (với <code>POST</code> / <code>SHORT_VIDEO</code>: <code>caption</code> không trống).</li><li><strong>Khi <code>requiresClientApproval = false</code></strong>: Ngay khi 100% phần của Task đạt <code>INTERNAL_APPROVED</code> và không còn công việc con tự do (<code>subtaskRole = null</code>) chưa hoàn thành → Hệ thống <strong>tự động chuyển Task cha sang <code>FINISHED</code></strong>, ghi nhận <code>finishedAt</code>, đóng <code>lastSubmission</code> với <code>outcome = &quot;APPROVED&quot;</code>, ghi bản ghi <code>task_approvals</code>, và đồng bộ <code>PostDocument</code> sang <code>SCHEDULED</code> (nếu có <code>publishDate</code>) hoặc <code>APPROVED</code>.</li><li><strong>Khi <code>requiresClientApproval = true</code></strong>: <ul><li>Ngay khi tất cả các phần đạt tối thiểu <code>INTERNAL_APPROVED</code> (trong đó còn ít nhất 1 phần <code>OUTPUT</code> đang chờ <code>Client</code> duyệt): Nếu Task cha đang ở <code>IN_PROGRESS</code>, hệ thống <strong>tự động chuyển Task cha sang <code>IN_REVIEW</code> với <code>reviewStep = &quot;CLIENT&quot;</code></strong> (và <code>PostDocument</code> sang <code>PENDING_APPROVAL</code>).</li><li>Ngay khi 100% các phần đạt <code>finalState = true</code> (mọi phần <code>INTERNAL</code> đạt <code>INTERNAL_APPROVED</code> và mọi phần <code>OUTPUT</code> đạt <code>CLIENT_APPROVED</code>) và không còn công việc con tự do mở → Hệ thống <strong>tự động chuyển Task cha sang <code>FINISHED</code></strong> (kể cả trong trường hợp <code>Client</code> đã duyệt sớm các phần <code>OUTPUT</code> trước khi <code>Manager</code> duyệt xong phần <code>INTERNAL</code> cuối cùng).</li></ul></li></ol></li><li><strong>AC-09 — Trả lại (<code>Return</code>) và Mở lại (<code>Reopen</code>) an toàn trước giờ xuất bản:</strong><ul><li><code>Owner</code> / <code>Manager</code> / <code>Supervisor</code> trả lại phần đang <code>SUBMITTED</code> (<code>RETURN</code>), hoặc <code>Client</code> trả lại phần <code>OUTPUT</code> đã duyệt (<code>CLIENT_RETURN</code>) đều <strong>bắt buộc nhập lý do không rỗng</strong> (tối đa <code>2.000</code> ký tự cho Section, <code>5.000</code> ký tự cho Task đơn).</li><li><code>Owner</code> và <code>Manager</code> được phép bấm <code>Mở lại</code> (<code>REOPEN</code>) một phần đã duyệt ngay cả khi Task cha đang ở <code>IN_PROGRESS</code>, <code>IN_REVIEW</code>, hoặc vừa chuyển sang <code>FINISHED</code> (miễn bài đăng/bản tin chưa bước vào <code>PUBLISHING</code> / <code>PUBLISHED</code> / <code>PROCESSING</code>).</li><li>Khi một phần trên Task đang <code>IN_REVIEW</code> hoặc <code>FINISHED</code> bị <code>CLIENT_RETURN</code> hoặc <code>REOPEN</code>: chỉ phần đó quay về <code>RETURNED</code> (giữ nguyên kết quả đã duyệt của các phần anh em khác), <code>Subtask</code> tương ứng quay về <code>IN_PROGRESS</code>, <strong>Task cha tự động quay về <code>IN_PROGRESS</code></strong> (<code>finishedAt = null</code>, <code>reviewStep = null</code>), và hệ thống tự động thu hồi lịch xuất bản (<code>PostService.cancelTaskSchedule</code> / <code>MailBatchService.cancelForTask</code>).</li></ul></li><li><strong>AC-10 — Khóa cứng chống nhảy cóc trạng thái (<code>Anti-Bypass Guard</code>):</strong><ul><li>Endpoint <code>PATCH /api/v1/workspaces/{workspaceId}/tasks/{taskId}/status</code> <strong>từ chối (<code>409 TASK_WORKFLOW_REQUIRED</code>)</strong> mọi yêu cầu đổi trực tiếp sang <code>IN_REVIEW</code> hoặc <code>FINISHED</code> đối với các Task thuộc phạm vi quy trình duyệt.</li><li>Thao tác đổi sang <code>CANCELLED</code> qua <code>PATCH /status</code> chỉ cho phép <code>Owner</code> và <code>Manager</code> (<code>Creator</code> bị từ chối <code>403 FORBIDDEN</code>).</li><li>Bảng Kanban (<code>useBoardDragAndDrop</code>) và Thanh thao tác hàng loạt (<code>TaskBulkActionBar</code>) tuân thủ cùng quy tắc: chặn thả thẻ / chọn hàng loạt sang <code>Chờ duyệt</code> hoặc <code>Hoàn thành</code>.</li></ul></li><li><strong>AC-11 — Giới hạn nghiêm ngặt <code>Hoàn tất &amp; Tự duyệt</code> (<code>Self-Approve</code>):</strong><ul><li>Endpoint <code>POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/self-approve</code> và nút <code>Hoàn tất &amp; Tự duyệt</code> trên giao diện (<code>TaskWorkflowContent</code>, <code>TaskEditorControls</code>, <code>TaskExportButton</code>) <strong>chỉ được phép hoạt động khi <code>workspaceMode = &quot;PERSONAL&quot;</code></strong> đối với <code>Owner</code> / <code>Manager</code>.</li><li>Trong chế độ <code>AGENCY</code> (kể cả khi <code>requiresClientApproval = false</code>), gọi <code>self-approve</code> bị chặn với mã lỗi <code>403 TASK_SELF_APPROVE_NOT_ALLOWED</code> và nút bị ẩn hoàn toàn trên mọi màn hình.</li></ul></li></ul><h3 id="_3-3-trai-nghiem-giao-dien-ui-ux-đa-ngon-ngu-i18n-giao-dien-sang-toi-light-dark" tabindex="-1">3.3. Trải nghiệm Giao diện (UI/UX), Đa ngôn ngữ (i18n) &amp; Giao diện Sáng/Tối (Light/Dark) <a class="header-anchor" href="#_3-3-trai-nghiem-giao-dien-ui-ux-đa-ngon-ngu-i18n-giao-dien-sang-toi-light-dark" aria-label="Permalink to &quot;3.3. Trải nghiệm Giao diện (UI/UX), Đa ngôn ngữ (i18n) &amp; Giao diện Sáng/Tối (Light/Dark)&quot;">​</a></h3><ul><li><strong>AC-12 — Chuẩn hóa <code>TaskStatusControl</code> ở góc trên Task Detail:</strong><ul><li>Khi Task ở trạng thái kết thúc (<code>FINISHED</code> hoặc <code>CANCELLED</code>) hoặc người dùng hiện tại không có bất kỳ thao tác chuyển trạng thái hợp lệ nào (<code>availableActions.length === 0</code>): hiển thị <strong>Badge trạng thái tĩnh</strong> (không hiển thị icon mũi tên <code>⌄</code> và không mở menu trống <em>&quot;Không có thao tác chuyển trạng thái&quot;</em>).</li><li>Hiển thị nhãn ngữ cảnh tiến độ rõ ràng ngay cạnh trạng thái: ví dụ <code>3/5 phần đã duyệt</code> (khi <code>IN_PROGRESS</code> trên Task chia phần), <code>Bước Quản lý</code> / <code>Bước Khách hàng</code> (khi <code>IN_REVIEW</code>), <code>Đã hoàn tất phê duyệt</code> (khi <code>FINISHED</code>).</li><li>Hỗ trợ đầy đủ cả các Task tạo thủ công (<code>sourceType = &quot;MANUAL&quot;</code> hoặc <code>&quot;CAMPAIGN_OUT_OF_SCOPE&quot;</code>) trên cả 8 loại <code>TaskType</code>.</li></ul></li><li><strong>AC-13 — Trang Phê duyệt tập trung (<code>/workspaces/:id/task-approvals</code>) hỗ trợ đủ 8 <code>TaskType</code>:</strong><ul><li>Danh sách chờ duyệt hiển thị toàn bộ 8 loại công việc (<code>POST</code>, <code>SHORT_VIDEO</code>, <code>SURVEY</code>, <code>EVENT_PLAN</code>, <code>PRESS_RECOMMENDATION</code>, <code>KOL_BOOKING</code>, <code>WORKSHOP</code>, <code>EMAIL_NEWSLETTER</code>), hỗ trợ lọc theo Loại công việc (<code>type</code>), Trạng thái (<code>status</code>) và từ khóa tìm kiếm.</li></ul></li><li><strong>AC-14 — Đồng bộ tức thì danh sách bên ngoài (<code>List</code>, <code>Kanban</code>, <code>Calendar</code>, <code>Gantt</code>):</strong><ul><li>Khi người dùng nộp phần, duyệt phần, trả lại phần, mở lại phần hoặc duyệt Task ngay trong <code>TaskDetailPanel</code> (Side Peek / Center Modal) hoặc quay về từ <code>Editor</code>, trạng thái dòng/thẻ công việc ở danh sách bên ngoài cập nhật ngay lập tức sang <code>Chờ duyệt</code> / <code>Hoàn thành</code> / <code>Đang làm</code> mà không cần tải lại trang trình duyệt.</li></ul></li><li><strong>AC-15 — Đa ngôn ngữ (<code>vi.json</code> + <code>en.json</code> key-parallel):</strong><ul><li>Toàn bộ nhãn trạng thái ngữ cảnh, thông báo chặn kéo-thả Kanban, bộ lọc loại công việc trên <code>/task-approvals</code>, và thông báo lỗi phân quyền dùng khóa dịch song song trong <code>src/i18n/locales/vi/tasks.json</code>, <code>src/i18n/locales/en/tasks.json</code>, <code>src/i18n/locales/vi/editor.json</code>, <code>src/i18n/locales/en/editor.json</code> — tuyệt đối không hardcode chuỗi tiếng Việt hay tiếng Anh trong JSX/TSX.</li></ul></li><li><strong>AC-16 — Tương thích Light / Dark Mode &amp; Responsive:</strong><ul><li>Mọi huy hiệu trạng thái tĩnh/động, tiến độ phần, thẻ phê duyệt và thông báo cảnh báo dùng semantic CSS variables (<code>bg-card</code>, <code>text-foreground</code>, <code>text-muted-foreground</code>, <code>border-border</code>) và cặp biến thể <code>dark:*</code> chuẩn mực, đảm bảo độ tương phản WCAG AA trên cả Light mode và Dark mode ở các khung nhìn <code>375px</code>, <code>768px</code>, <code>1440px</code>.</li></ul></li></ul><hr><h2 id="_4-state-machine-tong-hop" tabindex="-1">4. State Machine Tổng hợp <a class="header-anchor" href="#_4-state-machine-tong-hop" aria-label="Permalink to &quot;4. State Machine Tổng hợp&quot;">​</a></h2><h3 id="_4-1-task-co-chia-phan-vai-tro-roletask-true" tabindex="-1">4.1. Task Có Chia Phần &amp; Vai trò (<code>roleTask = true</code>) <a class="header-anchor" href="#_4-1-task-co-chia-phan-vai-tro-roletask-true" aria-label="Permalink to &quot;4.1. Task Có Chia Phần &amp; Vai trò (`roleTask = true`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Trạng thái Trước</th><th style="text-align:left;">Actor &amp; Sự kiện Nghiệp vụ</th><th style="text-align:left;">Trạng thái Sau (<code>TaskDocument</code> &amp; <code>PostDocument</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><code>TODO</code></td><td style="text-align:left;"><code>Coordinator</code> bấm <code>Start</code> <strong>HOẶC</strong> <code>Section Owner</code> / <code>Coordinator</code> lưu bản nháp phần đầu tiên</td><td style="text-align:left;"><code>IN_PROGRESS</code> (<code>firstStartedAt</code> được ghi nhận)</td></tr><tr><td style="text-align:left;"><code>IN_PROGRESS</code></td><td style="text-align:left;"><code>Section Owner</code> nộp phần (<code>SUBMIT</code>); <code>Owner</code> / <code>Manager</code> / <code>Supervisor</code> duyệt từng phần (<code>INTERNAL_APPROVED</code>), còn phần chưa xong</td><td style="text-align:left;">Giữ <code>IN_PROGRESS</code> (cập nhật tiến độ <code>X/Y</code> phần đã duyệt; các <code>Subtask</code> xong phần của mình tự chuyển <code>FINISHED</code>)</td></tr><tr><td style="text-align:left;"><code>IN_PROGRESS</code></td><td style="text-align:left;">Phần bắt buộc cuối cùng đạt <code>INTERNAL_APPROVED</code>, <code>requiresClientApproval = false</code>, không còn Free Subtask mở</td><td style="text-align:left;"><strong>Tự động chuyển <code>FINISHED</code></strong>, <code>reviewStep = null</code>, <code>Post</code> → <code>SCHEDULED</code> / <code>APPROVED</code></td></tr><tr><td style="text-align:left;"><code>IN_PROGRESS</code></td><td style="text-align:left;">Tất cả phần đạt tối thiểu <code>INTERNAL_APPROVED</code>, <code>requiresClientApproval = true</code>, còn phần <code>OUTPUT</code> chờ <code>Client</code></td><td style="text-align:left;"><strong>Tự động chuyển <code>IN_REVIEW</code> (<code>reviewStep = &quot;CLIENT&quot;</code>)</strong>, <code>Post</code> → <code>PENDING_APPROVAL</code></td></tr><tr><td style="text-align:left;"><code>IN_PROGRESS</code> / <code>IN_REVIEW (CLIENT)</code></td><td style="text-align:left;"><code>Client</code> duyệt phần <code>OUTPUT</code> cuối cùng (hoặc <code>Manager</code> duyệt phần <code>INTERNAL</code> cuối cùng sau khi <code>Client</code> đã duyệt xong các phần <code>OUTPUT</code>)</td><td style="text-align:left;"><strong>Tự động chuyển <code>FINISHED</code></strong>, <code>reviewStep = null</code>, <code>Post</code> → <code>SCHEDULED</code> / <code>APPROVED</code></td></tr><tr><td style="text-align:left;"><code>IN_REVIEW (CLIENT)</code> / <code>FINISHED</code> <em>(chưa đăng)</em></td><td style="text-align:left;"><code>Client</code> bấm <code>Return</code> (kèm lý do) <strong>HOẶC</strong> <code>Owner</code> / <code>Manager</code> bấm <code>Reopen</code> 1 phần</td><td style="text-align:left;">Phần đó → <code>RETURNED</code>, <code>Subtask</code> đó → <code>IN_PROGRESS</code>, <strong>Task cha → <code>IN_PROGRESS</code></strong>, hủy lịch đăng tự động</td></tr></tbody></table><h3 id="_4-2-task-đon-khong-chia-subtask-vai-tro-roletask-false" tabindex="-1">4.2. Task Đơn Không Chia Subtask Vai trò (<code>roleTask = false</code>) <a class="header-anchor" href="#_4-2-task-đon-khong-chia-subtask-vai-tro-roletask-false" aria-label="Permalink to &quot;4.2. Task Đơn Không Chia Subtask Vai trò (`roleTask = false`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Trạng thái Trước</th><th style="text-align:left;">Actor &amp; Sự kiện Nghiệp vụ</th><th style="text-align:left;">Trạng thái Sau</th></tr></thead><tbody><tr><td style="text-align:left;"><code>TODO</code></td><td style="text-align:left;"><code>Coordinator</code> (<code>Owner</code> / <code>Manager</code> / <code>Creator</code> được giao) bấm <code>Start</code></td><td style="text-align:left;"><code>IN_PROGRESS</code></td></tr><tr><td style="text-align:left;"><code>IN_PROGRESS</code></td><td style="text-align:left;"><code>Coordinator</code> là <code>Creator</code> (hoặc có <code>Supervisor</code> khác) bấm <code>Submit</code></td><td style="text-align:left;"><code>IN_REVIEW</code> / <code>MANAGER</code> (<code>Post</code> → <code>PENDING_APPROVAL</code>)</td></tr><tr><td style="text-align:left;"><code>IN_PROGRESS</code></td><td style="text-align:left;"><code>Coordinator</code> là <code>Owner</code> / <code>Manager</code> tự giám sát bấm <code>Submit</code></td><td style="text-align:left;"><code>IN_REVIEW</code> / <code>CLIENT</code> <em>(nếu cần <code>Client</code>)</em> hoặc <code>FINISHED</code> <em>(nếu không cần <code>Client</code>)</em></td></tr><tr><td style="text-align:left;"><code>IN_REVIEW</code> / <code>MANAGER</code></td><td style="text-align:left;"><code>Owner</code> / <code>Manager</code> / <code>Task Supervisor</code> (khác <code>Creator</code> nộp) bấm <code>Approve</code></td><td style="text-align:left;"><code>FINISHED</code> <em>(nếu không cần <code>Client</code>)</em> hoặc <code>IN_REVIEW</code> / <code>CLIENT</code> <em>(nếu cần <code>Client</code>)</em></td></tr><tr><td style="text-align:left;"><code>IN_REVIEW</code> / <code>CLIENT</code></td><td style="text-align:left;">Một <code>Client</code> active bất kỳ bấm <code>Approve</code></td><td style="text-align:left;"><code>FINISHED</code> (<code>Post</code> → <code>SCHEDULED</code> / <code>APPROVED</code>)</td></tr><tr><td style="text-align:left;"><code>IN_REVIEW</code> / <code>MANAGER</code> hoặc <code>CLIENT</code></td><td style="text-align:left;">Người duyệt hợp lệ bấm <code>Reject</code> (có lý do bắt buộc)</td><td style="text-align:left;"><code>IN_PROGRESS</code>, <code>reviewStep = null</code> (<code>Post</code> → <code>DRAFT</code>; lần gửi sau <code>approvalRound + 1</code>)</td></tr><tr><td style="text-align:left;"><code>IN_REVIEW</code> / <code>MANAGER</code> <em>(chưa có decision)</em></td><td style="text-align:left;"><code>Coordinator</code> bấm <code>Withdraw</code></td><td style="text-align:left;"><code>IN_PROGRESS</code>, <code>reviewStep = null</code> (<code>Post</code> → <code>DRAFT</code>)</td></tr></tbody></table><hr><h2 id="_5-api-contract-quy-tac-kiem-tra-quyen" tabindex="-1">5. API Contract &amp; Quy tắc Kiểm tra Quyền <a class="header-anchor" href="#_5-api-contract-quy-tac-kiem-tra-quyen" aria-label="Permalink to &quot;5. API Contract &amp; Quy tắc Kiểm tra Quyền&quot;">​</a></h2><p>Prefix chuẩn: <code>/api/v1/workspaces/{workspaceId}/tasks/{taskId}</code></p><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Vai trò Được Phép</th><th style="text-align:left;">Ràng buộc Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /review</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Trả về <code>status</code>, <code>reviewStep</code>, <code>approvalRound</code>, <code>workflowRevision</code>, <code>allowedActions</code>, <code>blockedReason</code>.</td></tr><tr><td style="text-align:left;"><code>POST /submit</code></td><td style="text-align:left;"><code>Coordinator</code> (<code>task.assigneeId</code>)</td><td style="text-align:left;">Chuyển Task đơn sang <code>IN_REVIEW</code> (hoặc chốt các phần không chủ sở hữu). Bắt buộc <code>caption</code> không rỗng với <code>POST</code>/<code>SHORT_VIDEO</code>.</td></tr><tr><td style="text-align:left;"><code>POST /withdraw</code></td><td style="text-align:left;"><code>Coordinator</code> (<code>task.assigneeId</code>)</td><td style="text-align:left;">Thu hồi khi đang <code>IN_REVIEW / MANAGER</code> và chưa có quyết định.</td></tr><tr><td style="text-align:left;"><code>POST /approve</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Task Supervisor</code> <em>(bước <code>MANAGER</code>)</em>; <code>Client</code> <em>(bước <code>CLIENT</code>)</em></td><td style="text-align:left;">Chặn tự duyệt đối với <code>Creator</code>; cập nhật CAS nguyên tử Task + Post + <code>task_approvals</code>.</td></tr><tr><td style="text-align:left;"><code>POST /reject</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Task Supervisor</code> <em>(bước <code>MANAGER</code>)</em>; <code>Client</code> <em>(bước <code>CLIENT</code>)</em></td><td style="text-align:left;">Bắt buộc <code>comment</code> không trắng (≤ <code>5.000</code> ký tự); đưa Task về <code>IN_PROGRESS</code>.</td></tr><tr><td style="text-align:left;"><code>POST /self-approve</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code> (<strong>CHỈ khi <code>workspaceMode = &quot;PERSONAL&quot;</code></strong>)</td><td style="text-align:left;">Trả <code>403 TASK_SELF_APPROVE_NOT_ALLOWED</code> nếu gọi trên Workspace chế độ <code>AGENCY</code>.</td></tr><tr><td style="text-align:left;"><code>GET /sections</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Lọc ẩn toàn bộ phần <code>INTERNAL</code> đối với <code>Client</code> và <code>Creator</code> ngoài Task.</td></tr><tr><td style="text-align:left;"><code>PATCH /sections/{sectionKey}</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Coordinator</code>, <code>Section Owner</code></td><td style="text-align:left;">Lưu nháp theo CAS <code>expectedRevision</code>; tự mở <code>TODO → IN_PROGRESS</code> nếu đủ điều kiện.</td></tr><tr><td style="text-align:left;"><code>POST /sections/{sectionKey}/submit</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Coordinator</code>, <code>Section Owner</code></td><td style="text-align:left;">Chụp <code>TaskSectionVersion</code> bất biến, chuyển phần sang <code>SUBMITTED</code>.</td></tr><tr><td style="text-align:left;"><code>POST /sections/{sectionKey}/approve</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Supervisor</code> <em>(nội bộ)</em>; <code>Client</code> <em>(phần <code>OUTPUT</code>)</em></td><td style="text-align:left;">Duyệt phần; kích hoạt <strong>Auto-Settlement</strong> chuyển Task cha sang <code>IN_REVIEW (CLIENT)</code> hoặc <code>FINISHED</code> khi đủ 100% điều kiện.</td></tr><tr><td style="text-align:left;"><code>POST /sections/{sectionKey}/return</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Supervisor</code> <em>(nội bộ)</em>; <code>Client</code> <em>(phần <code>OUTPUT</code>)</em></td><td style="text-align:left;">Bắt buộc <code>note</code> (≤ <code>2.000</code> ký tự); nếu Task đang <code>IN_REVIEW</code>/<code>FINISHED</code> thì mở lại <code>IN_PROGRESS</code> và hủy lịch đăng.</td></tr><tr><td style="text-align:left;"><code>POST /sections/{sectionKey}/reopen</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Mở lại phần đã duyệt (kể cả khi Task vừa <code>FINISHED</code> mà bài chưa đăng), tự đưa Task về <code>IN_PROGRESS</code> và hủy lịch đăng.</td></tr><tr><td style="text-align:left;"><code>PATCH /status</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Coordinator</code> <em>(giới hạn)</em></td><td style="text-align:left;"><strong>Cấm</strong> <code>IN_REVIEW</code> và <code>FINISHED</code> (<code>409 TASK_WORKFLOW_REQUIRED</code>); <code>CANCELLED</code> chỉ cho <code>Owner</code>/<code>Manager</code>.</td></tr></tbody></table><hr><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong><code>400 VALIDATION_ERROR</code> / <code>INVALID_TASK_SUPERVISOR</code></strong>: Thiếu lý do trả bài/từ chối, <code>caption</code> rỗng khi nộp bài <code>POST</code>/<code>SHORT_VIDEO</code>, hoặc gán <code>supervisorId</code> trùng với <code>assigneeId</code> của <code>Creator</code>.</li><li><strong><code>403 FORBIDDEN</code> / <code>WRONG_APPROVAL_STEP</code> / <code>TASK_SELF_APPROVE_NOT_ALLOWED</code></strong>: Sai vai trò duyệt, <code>Creator</code> tự duyệt bài mình, <code>Creator</code> ngoài Task bấm <code>Publish</code> hoặc sửa <code>partners</code>, hoặc gọi <code>self-approve</code> trong Workspace <code>AGENCY</code>.</li><li><strong><code>409 TASK_WORKFLOW_REQUIRED</code> / <code>TASK_REVISION_CONFLICT</code> / <code>POST_CONTENT_CONFLICT</code></strong>: Cố tình đổi thẳng sang <code>FINISHED</code> / <code>IN_REVIEW</code> qua <code>PATCH /status</code> (Kanban/Bulk), hoặc dữ liệu màn hình đã cũ khi hai người thao tác đồng thời (giữ nguyên nháp/nhận xét đang nhập để người dùng tải lại).</li><li><strong>Bài đã xuất bản thật (<code>PUBLISHING</code> / <code>PUBLISHED</code>)</strong>: Khi <code>PostDocument</code> đã đi vào hàng đợi xuất bản hoặc đã đăng lên mạng xã hội, mọi thao tác <code>REOPEN</code> / <code>CLIENT_RETURN</code> trên phần nội dung của bài đăng đó bị khóa để bảo toàn tính toàn vẹn lịch sử xuất bản.</li></ul><hr><h2 id="_7-definition-of-done-out-of-scope" tabindex="-1">7. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_7-definition-of-done-out-of-scope" aria-label="Permalink to &quot;7. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong><ol><li>Toàn bộ 16 tiêu chí nghiệm thu (<code>AC-01</code> – <code>AC-16</code>) được triển khai đồng bộ trên <code>brandhub-business-service</code> và <code>brandhub-web</code>.</li><li>Bộ khóa dịch <code>vi</code> / <code>en</code> song song 100%, không hardcode chuỗi văn bản; giao diện đạt chuẩn Light/Dark mode trên Mobile/Tablet/Desktop.</li><li>Toàn bộ kiểm thử đơn vị và tích hợp trong <a href="./test.html">test.md</a> đạt <code>Pass</code> 100%.</li></ol></li><li><strong>Out of Scope:</strong> Các tính năng đã loại khỏi phạm vi dự án theo <code>AGENTS.md</code> (không có Livestream, không hạ cấp gói cước, không quét đạo văn/bản quyền, chỉ hỗ trợ đúng 4 nền tảng <code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code>).</li><li><strong>Tham chiếu BA:</strong> <a href="./../../../../ba/13-task-status-and-approval-governance.html">13-task-status-and-approval-governance.md</a> · <a href="./../../../../ba/05-content-task-workflow.html">05-content-task-workflow.md</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">10-roles-permissions-matrix.md</a> · <a href="./../../../../ba/12-state-machines.html">12-state-machines.md</a>.</li></ul>',34)])])}const p=o(n,[["render",a]]);export{u as __pageData,p as default};
